CREATE TABLE "public"."user_role_change_audit" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "actor_user_id" INTEGER NOT NULL REFERENCES "public"."user" ("id") ON UPDATE CASCADE,
  "target_user_id" INTEGER NOT NULL REFERENCES "public"."user" ("id") ON UPDATE CASCADE,
  "old_roles" TEXT [] NOT NULL,
  "new_roles" TEXT [] NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("id")
);

CREATE INDEX "idx_user_role_change_audit_actor_user_id" ON "public"."user_role_change_audit" ("actor_user_id");

CREATE INDEX "idx_user_role_change_audit_target_user_id" ON "public"."user_role_change_audit" ("target_user_id");

CREATE INDEX "idx_user_role_change_audit_created_at" ON "public"."user_role_change_audit" ("created_at");
